CREATE OR REPLACE FUNCTION public.get_organization_student_capacity(p_organization_id uuid, p_requested_count integer DEFAULT 1)
 RETURNS TABLE(current_students integer, max_students integer, is_unlimited boolean, can_add boolean, remaining_students integer, subscription_plan text, limit_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan text;
  v_custom integer;
  v_plan_limit integer;
  v_max integer;
  v_source text;
  v_current integer := 0;
  v_requested integer := GREATEST(COALESCE(p_requested_count, 1), 0);
  v_uid uuid := auth.uid();
  v_jwt_role text := COALESCE(
    current_setting('request.jwt.claim.role', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role')
  );
  v_is_service boolean := (v_jwt_role = 'service_role');
  v_allowed boolean := false;
  v_month date := (date_trunc('month', timezone('Europe/Moscow', now())))::date;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF v_is_service THEN
    v_allowed := true;
  ELSIF v_uid IS NOT NULL THEN
    IF public.has_role(v_uid, 'admin'::public.app_role) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.user_roles ur
      JOIN public.profiles p ON p.user_id = ur.user_id
      WHERE ur.user_id = v_uid
        AND ur.role = 'organization'::public.app_role
        AND p.organization_id = p_organization_id
    ) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.org_staff os
      WHERE os.user_id = v_uid
        AND os.organization_id = p_organization_id
        AND (os.expires_at IS NULL OR os.expires_at > now())
    ) AND (
      public.has_org_staff_permission(v_uid, p_organization_id, 'students.read')
      OR public.has_org_staff_permission(v_uid, p_organization_id, 'students.write')
    ) THEN
      v_allowed := true;
    ELSIF EXISTS (
      SELECT 1 FROM public.companies c
      WHERE c.organization_id = p_organization_id
        AND (
          c.user_id = v_uid
          OR public.has_company_access(v_uid, c.id, 'viewer'::public.company_staff_role)
        )
    ) THEN
      v_allowed := true;
    END IF;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'access denied to organization capacity' USING ERRCODE = '42501';
  END IF;

  SELECT o.subscription_plan, o.custom_max_students
    INTO v_plan, v_custom
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF v_plan IS NULL THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  v_plan_limit := CASE lower(coalesce(v_plan, 'free'))
    WHEN 'free' THEN 10
    WHEN 'start' THEN 100
    WHEN 'standard' THEN 200
    WHEN 'professional' THEN -1
    WHEN 'maximum' THEN -1
    ELSE 10
  END;

  IF v_custom IS NULL THEN
    v_max := v_plan_limit;
    v_source := 'plan';
  ELSE
    v_max := v_custom;
    v_source := 'custom';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_billing_agreements agreement
    WHERE agreement.organization_id = p_organization_id
      AND agreement.effective_from <= (now() AT TIME ZONE 'Europe/Moscow')::date
      AND (agreement.effective_to IS NULL
        OR agreement.effective_to > (now() AT TIME ZONE 'Europe/Moscow')::date)
  ) THEN
    v_max := -1;
    v_source := 'postpaid';
  END IF;

  SELECT COALESCE(u.students_added_count, 0)
    INTO v_current
  FROM public.organization_usage u
  WHERE u.organization_id = p_organization_id
    AND u.month_start = v_month;

  v_current := COALESCE(v_current, 0);

  current_students := v_current;
  max_students := v_max;
  subscription_plan := v_plan;
  limit_source := v_source;
  is_unlimited := (v_max = -1);

  IF is_unlimited THEN
    remaining_students := -1;
    can_add := true;
  ELSIF v_max <= 0 THEN
    remaining_students := 0;
    can_add := false;
  ELSE
    remaining_students := GREATEST(v_max - v_current, 0);
    can_add := (v_current + v_requested) <= v_max;
  END IF;

  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_student_profile_with_capacity(p_organization_id uuid, p_user_id uuid, p_full_name text, p_email text, p_login text, p_generated_password text, p_company_id uuid, p_student_group_id uuid, p_region text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan text;
  v_custom int;
  v_plan_limit int;
  v_max int;
  v_source text;
  v_current int := 0;
  v_existing_org uuid;
  v_existing_archived timestamptz;
  v_month date := (date_trunc('month', timezone('Europe/Moscow', now())))::date;
  v_jwt_role text := COALESCE(
    current_setting('request.jwt.claim.role', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role')
  );
BEGIN
  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service role required' USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'organization_id and user_id are required';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_organization_id::text, 42));

  SELECT o.subscription_plan, o.custom_max_students INTO v_plan, v_custom
  FROM public.organizations o WHERE o.id = p_organization_id;
  IF v_plan IS NULL THEN RAISE EXCEPTION 'organization not found' USING ERRCODE='P0002'; END IF;

  v_plan_limit := CASE lower(coalesce(v_plan,'free'))
    WHEN 'free' THEN 10 WHEN 'start' THEN 100 WHEN 'standard' THEN 200
    WHEN 'professional' THEN -1 WHEN 'maximum' THEN -1 ELSE 10 END;
  IF v_custom IS NULL THEN v_max := v_plan_limit; v_source:='plan';
  ELSE v_max := v_custom; v_source:='custom'; END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_billing_agreements agreement
    WHERE agreement.organization_id = p_organization_id
      AND agreement.effective_from <= (now() AT TIME ZONE 'Europe/Moscow')::date
      AND (agreement.effective_to IS NULL
        OR agreement.effective_to > (now() AT TIME ZONE 'Europe/Moscow')::date)
  ) THEN
    v_max := -1;
    v_source := 'postpaid';
  END IF;

  INSERT INTO public.organization_usage (organization_id, month_start, students_added_count)
  VALUES (p_organization_id, v_month, 0)
  ON CONFLICT (organization_id, month_start) DO NOTHING;

  SELECT students_added_count INTO v_current FROM public.organization_usage
  WHERE organization_id = p_organization_id AND month_start = v_month FOR UPDATE;
  v_current := COALESCE(v_current, 0);

  SELECT p.organization_id, p.archived_at INTO v_existing_org, v_existing_archived
  FROM public.profiles p WHERE p.user_id = p_user_id;

  IF v_existing_org IS NOT NULL AND v_existing_org = p_organization_id THEN
    IF v_existing_archived IS NOT NULL THEN
      RETURN jsonb_build_object('success',false,'code','STUDENT_ARCHIVED','message','Ученик находится в архиве. Восстановите его из архива вручную.','current_students',v_current,'max_students',v_max,'is_unlimited',v_max=-1,'limit_source',v_source);
    END IF;
    UPDATE public.profiles SET
      full_name=COALESCE(NULLIF(p_full_name,''),full_name),
      email=COALESCE(NULLIF(p_email,''),email),
      company_id=COALESCE(p_company_id,company_id),
      student_group_id=COALESCE(p_student_group_id,student_group_id),
      region=COALESCE(NULLIF(p_region,''),region)
    WHERE user_id=p_user_id;
    INSERT INTO public.user_roles(user_id, role) VALUES (p_user_id, 'student'::public.app_role) ON CONFLICT (user_id) DO NOTHING;
    RETURN jsonb_build_object('success',true,'is_existing',true,'current_students',v_current,'max_students',v_max,'is_unlimited',v_max=-1,'limit_source',v_source);
  END IF;

  IF v_existing_org IS NOT NULL AND v_existing_org <> p_organization_id THEN
    RETURN jsonb_build_object('success',false,'code','PROFILE_IN_OTHER_ORG','message','Профиль пользователя уже привязан к другой организации.','max_students',v_max,'is_unlimited',v_max=-1,'limit_source',v_source);
  END IF;

  IF v_max <> -1 AND v_current >= v_max THEN
    RETURN jsonb_build_object('success',false,'code','STUDENT_LIMIT_EXCEEDED','message',format('Достигнут месячный лимит новых учеников: %s из %s',v_current,v_max),'current_students',v_current,'max_students',v_max,'is_unlimited',false,'limit_source',v_source);
  END IF;

  INSERT INTO public.profiles (user_id, full_name, email, login, generated_password, organization_id, company_id, student_group_id, region)
  VALUES (p_user_id, p_full_name, NULLIF(p_email,''), NULLIF(p_login,''), NULLIF(p_generated_password,''), p_organization_id, p_company_id, p_student_group_id, NULLIF(p_region,''))
  ON CONFLICT (user_id) DO UPDATE SET
    full_name=EXCLUDED.full_name,
    email=COALESCE(EXCLUDED.email, public.profiles.email),
    login=COALESCE(EXCLUDED.login, public.profiles.login),
    generated_password=COALESCE(EXCLUDED.generated_password, public.profiles.generated_password),
    organization_id=EXCLUDED.organization_id,
    company_id=COALESCE(EXCLUDED.company_id, public.profiles.company_id),
    student_group_id=COALESCE(EXCLUDED.student_group_id, public.profiles.student_group_id),
    region=COALESCE(EXCLUDED.region, public.profiles.region);

  INSERT INTO public.user_roles(user_id, role) VALUES (p_user_id, 'student'::public.app_role) ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.organization_usage SET students_added_count=students_added_count+1
  WHERE organization_id=p_organization_id AND month_start=v_month;

  RETURN jsonb_build_object('success',true,'is_existing',false,'current_students',v_current+1,'max_students',v_max,'is_unlimited',v_max=-1,'limit_source',v_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.account_deletion_erase_data(p_request_id uuid, p_receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'storage'
AS $function$
DECLARE j public.account_deletion_jobs%ROWTYPE; u uuid; r record; v_org uuid; current_snapshot jsonb;
BEGIN
 SELECT * INTO j FROM public.account_deletion_jobs WHERE id=p_request_id AND receipt_hash=p_receipt_hash FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code','INVALID_RECEIPT'); END IF;
 IF j.consent_version IS DISTINCT FROM 'full-personal-data-v1' THEN RETURN jsonb_build_object('code','CONSENT_REQUIRED'); END IF;
 IF j.state='deleted' THEN RETURN jsonb_build_object('erased',true); END IF;
 IF j.state<>'cleanup_pending' THEN RETURN jsonb_build_object('code','NOT_CONFIRMED'); END IF;
 u:=j.user_id;
 PERFORM pg_advisory_xact_lock(hashtextextended(u::text,42007));
 IF jsonb_array_length(public.account_deletion_files(u))>0 OR EXISTS(SELECT 1 FROM storage.objects o JOIN jsonb_array_elements(j.files) f ON f->>'bucket'=o.bucket_id AND f->>'path'=o.name) THEN RETURN jsonb_build_object('code','DELETION_UNAVAILABLE'); END IF;
 current_snapshot:=public.account_deletion_snapshot(u);
 IF jsonb_array_length(current_snapshot->'blockers')>0 THEN RETURN jsonb_build_object('code','PLAN_CHANGED'); END IF;
 -- Delete the enrollment before lesson progress: the live progress trigger
 -- then has no enrollment to reset. CSZ/issued/shared cases failed in preview.
 PERFORM set_config('sintagma.account_deletion_erase_user',u::text,true);
 PERFORM public.uc_erase_admission_cases(u);
 PERFORM public.uc_erase_identification_data(u);
 DELETE FROM public.audit_logs WHERE entity_id=u::text OR (entity_type='enrollment' AND entity_id IN(SELECT id::text FROM public.enrollments WHERE user_id=u));
 UPDATE public.audit_logs SET user_id='00000000-0000-0000-0000-000000000000',user_name=NULL,ip_address=NULL,user_agent=NULL WHERE user_id=u;
 UPDATE public.role_audit_log SET performed_by=NULL,performed_by_name=NULL,details=CASE WHEN details->>'from_user_id'=u::text THEN details-'from_user_id' ELSE details END WHERE performed_by=u AND target_user_id IS DISTINCT FROM u;
 UPDATE public.student_deletion_log SET deleted_by=NULL,deleted_by_name=NULL,deleted_by_email=NULL WHERE deleted_by=u AND student_id IS DISTINCT FROM u;
 DELETE FROM public.final_test_photo_challenges WHERE user_id=u;
 DELETE FROM public.test_attempts WHERE user_id=u;
 DELETE FROM public.test_attempt_start_requests WHERE user_id=u;
 DELETE FROM public.test_attempt_sessions WHERE user_id=u;
 DELETE FROM public.homework_submissions WHERE student_id=u;
 DELETE FROM public.journal_entries WHERE user_id=u;
 DELETE FROM public.group_class_journal_marks WHERE user_id=u;
 DELETE FROM public.training_plans WHERE user_id=u;
 DELETE FROM public.student_group_memberships WHERE user_id=u;
 DELETE FROM public.student_roster_removals WHERE user_id=u;
 DELETE FROM public.enrollments WHERE user_id=u;
 DELETE FROM public.lesson_progress WHERE user_id=u;
 -- on_enrollment_delete inserts an event; remove it after that trigger.
 DELETE FROM public.enrollment_history WHERE user_id=u;
 DELETE FROM public.student_deletion_log WHERE student_id=u;
 DELETE FROM public.support_messages WHERE conversation_id IN (SELECT id FROM public.support_conversations WHERE user_id=u) OR sender_user_id=u;
 DELETE FROM public.support_conversations WHERE user_id=u;
 DELETE FROM public.document_signatures WHERE (sender_user_id=u OR recipient_user_id=u) AND signed_at IS NULL AND sender_signed_at IS NULL AND status<>'signed';
 DELETE FROM public.consent_documents WHERE student_user_id=u;
 DELETE FROM public.org_contracts WHERE student_user_id=u AND approved_at IS NULL AND signed_at IS NULL AND status IN ('draft','cancelled');
 FOR r IN SELECT * FROM (VALUES
  ('admin_org_messages','sender_user_id'),
  ('admin_staff','user_id'),
  ('ai_prompt_templates','user_id'),
  ('ai_tutor_sessions','user_id'),
  ('ai_usage_log','user_id'),
  ('call_log_listens','listener_user_id'),
  ('chat_group_members','user_id'),
  ('chat_group_messages','sender_user_id'),
  ('chat_messages','user_id'),
  ('chat_notification_settings','user_id'),
  ('client_error_logs','user_id'),
  ('company_staff','user_id'),
  ('course_access_log','user_id'),
  ('course_reminders','user_id'),
  ('course_requests','user_id'),
  ('course_review_grants','user_id'),
  ('data_subject_requests','user_id'),
  ('exolve_sip_accounts','user_id'),
  ('final_test_photo_challenges','user_id'),
  ('module_access_overrides','user_id'),
  ('notification_preferences','user_id'),
  ('org_general_messages','sender_user_id'),
  ('org_notifications','user_id'),
  ('org_staff','user_id'),
  ('org_student_messages','sender_user_id'),
  ('org_student_messages','student_user_id'),
  ('organization_offer_acceptances','user_id'),
  ('partner_applications','user_id'),
  ('pending_enrollments','user_id'),
  ('pep_agreements','user_id'),
  ('pipeline_runs','user_id'),
  ('registration_attempts','user_id'),
  ('student_consents','user_id'),
  ('student_frdo_data','user_id'),
  ('student_identity_documents','user_id'),
  ('student_login_history','user_id'),
  ('student_login_tokens','user_id'),
  ('student_notifications','user_id'),
  ('support_requests','user_id'),
  ('testimonials','user_id'),
  ('user_achievements','user_id'),
  ('video_identifications','user_id'),
  ('webinar_participants','user_id')
 ) x(t,c) LOOP
  EXECUTE format('DELETE FROM public.%I WHERE %I=$1',r.t,r.c) USING u;
 END LOOP;
 -- Nullable author references are attribution, not ownership of client data.
 FOR r IN SELECT * FROM (VALUES
  ('admin_generated_documents','created_by'),
  ('ai_settings','updated_by'),
  ('app_settings','updated_by'),
  ('company_documents','uploaded_by'),
  ('consent_documents','created_by'),
  ('course_review_grants','revoked_by'),
  ('enrollment_history','performed_by'),
  ('exolve_sip_accounts','created_by'),
  ('landing_content','updated_by'),
  ('marketplace_settings','updated_by'),
  ('organization_comments','created_by'),
  ('organization_reminders','created_by'),
  ('platform_announcements','created_by'),
  ('sales_tasks','assigned_user_id'),
  ('skillspace_import_jobs','created_by'),
  ('staff_invitations','accepted_user_id'),
  ('student_login_tokens','created_by'),
  ('video_identifications','verified_by')
 ) x(t,c) LOOP
  EXECUTE format('UPDATE public.%I SET %I=NULL WHERE %I=$1',r.t,r.c,r.c) USING u;
 END LOOP;
 DELETE FROM public.user_roles WHERE user_id=u;
 DELETE FROM public.profiles WHERE user_id=u;
 -- org_staff DELETE creates a role-audit event: clear it after all staff/profile
 -- triggers; never leave the target UUID hidden in its own account history.
 DELETE FROM public.role_audit_log WHERE target_user_id=u;
 DELETE FROM public.audit_logs WHERE entity_id=u::text;
 IF (j.snapshot->>'emptyOrganization')::boolean THEN
  v_org:=(j.snapshot->>'organizationId')::uuid;
  -- Recheck under the organization lock; a concurrent invitation/registration
  -- must never be swept into this operation.
  PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE organization_id=v_org AND user_id<>u) OR EXISTS(SELECT 1 FROM public.org_staff WHERE organization_id=v_org) THEN RAISE EXCEPTION 'Organization changed during deletion'; END IF;
  DELETE FROM public.organizations WHERE id=v_org;
 END IF;
 DELETE FROM public.uc_identification_write_contexts WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND kind IN('subject_erase','reviewer_erase') AND user_id=u;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(public.account_deletion_personal_row_counts(u)) n WHERE (n->>'count')::bigint>0) THEN RAISE EXCEPTION 'Personal data erasure is incomplete'; END IF;
 UPDATE public.account_deletion_jobs SET data_erased=true WHERE id=j.id;
 RETURN jsonb_build_object('erased',true);
END;$function$

CREATE OR REPLACE FUNCTION public.log_enrollment_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.enrollment_history (enrollment_id, user_id, course_id, action, performed_by)
    VALUES (NEW.id, NEW.user_id, NEW.course_id, 'enrolled', auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.enrollment_history (enrollment_id, user_id, course_id, action, performed_by)
    VALUES (OLD.id, OLD.user_id, OLD.course_id, 'unenrolled', auth.uid());
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_profile_group_course_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_course_id uuid;
  v_group_org_id uuid;
  v_course_org_id uuid;
BEGIN
  IF NEW.student_group_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- SHARE, not KEY SHARE: course_id is not a key, but changing it must wait for
  -- registration/enrollment to commit. Held until transaction end. The group
  -- updater's AFTER trigger then sees committed membership at READ COMMITTED.
  -- Native composite FKs protect tenant references under stronger isolation too;
  -- this is not a claim of tested multi-session enrollment synchronization.
  SELECT g.course_id, g.organization_id INTO v_course_id, v_group_org_id
  FROM public.student_groups g WHERE g.id = NEW.student_group_id
  FOR SHARE;
  IF NOT FOUND THEN
    -- Cascading actions can already have deleted the group before this queued
    -- AFTER event runs. Its native SET NULL action clears the actual membership.
    IF TG_OP = 'UPDATE' AND NEW.organization_id IS NULL AND OLD.organization_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = OLD.organization_id)
    THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'student_group_not_found' USING ERRCODE = '23503';
  END IF;

  -- Preserve the pre-existing organization deletion actions: profiles.org uses
  -- ON DELETE SET NULL, while groups use ON DELETE CASCADE. During that cascade
  -- only, the organization is already gone and group deletion will clear the
  -- membership. Do not create an enrollment from this intermediate row.
  IF TG_OP = 'UPDATE' AND NEW.organization_id IS NULL
     AND OLD.organization_id IS NOT DISTINCT FROM v_group_org_id
     AND NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = v_group_org_id)
  THEN
    RETURN NEW;
  END IF;

  IF NEW.organization_id IS NULL OR v_group_org_id IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'student_group_organization_mismatch' USING ERRCODE = '23503';
  END IF;

  IF v_course_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT c.organization_id INTO v_course_org_id
  FROM public.courses c WHERE c.id = v_course_id FOR SHARE;
  IF NOT FOUND OR v_course_org_id IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'group_course_organization_mismatch' USING ERRCODE = '23503';
  END IF;

  -- A normal profile save may explicitly SET the unchanged identity fields.
  -- Validate them above, but do not undo an intentional enrollment deletion.
  IF TG_OP = 'UPDATE'
     AND NEW.student_group_id IS NOT DISTINCT FROM OLD.student_group_id
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
     AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id
  THEN
    RETURN NEW;
  END IF;

  -- Existing active/completed/expired enrollments, progress and expiry are never
  -- overwritten or revived. A violation aborts the whole profile/quota RPC.
  INSERT INTO public.enrollments (user_id, course_id, status, progress, time_spent)
  VALUES (NEW.user_id, v_course_id, 'active', 0, 0)
  ON CONFLICT (user_id, course_id) DO NOTHING;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_group_course_enrollments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_course_org_id uuid;
BEGIN
  IF NEW.course_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT c.organization_id INTO v_course_org_id
  FROM public.courses c WHERE c.id = NEW.course_id FOR SHARE;
  IF NOT FOUND OR v_course_org_id IS DISTINCT FROM NEW.organization_id THEN
    RAISE EXCEPTION 'group_course_organization_mismatch' USING ERRCODE = '23503';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.student_group_id = NEW.id
      AND p.organization_id IS DISTINCT FROM NEW.organization_id
  ) THEN
    RAISE EXCEPTION 'student_group_organization_mismatch' USING ERRCODE = '23503';
  END IF;

  -- Group settings saves include course_id even for rename/price/date edits.
  -- Tenant validation still runs, but an unchanged association must not enroll.
  IF TG_OP = 'UPDATE'
     AND NEW.course_id IS NOT DISTINCT FROM OLD.course_id
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
  THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.enrollments (user_id, course_id, status, progress, time_spent)
  SELECT p.user_id, NEW.course_id, 'active', 0, 0
  FROM public.profiles p
  WHERE p.student_group_id = NEW.id AND p.organization_id = NEW.organization_id
  ON CONFLICT (user_id, course_id) DO NOTHING;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_complete_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.progress >= 100 AND NEW.status != 'completed' THEN
    NEW.status := 'completed';
    NEW.completed_at := now();
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calc_enrollment_expires_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.access_days IS NOT NULL AND NEW.access_days > 0 THEN
    NEW.expires_at := NEW.started_at + (NEW.access_days || ' days')::interval;
  ELSIF NEW.access_days IS NULL THEN
    NEW.expires_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalc_enrollment_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_course_id uuid;
  v_user_id uuid;
  v_total int;
  v_done int;
  v_progress int;
BEGIN
  -- Определяем урок (для DELETE берём OLD)
  IF TG_OP = 'DELETE' THEN
    SELECT course_id INTO v_course_id FROM lessons WHERE id = OLD.lesson_id;
    v_user_id := OLD.user_id;
  ELSE
    SELECT course_id INTO v_course_id FROM lessons WHERE id = NEW.lesson_id;
    v_user_id := NEW.user_id;
  END IF;

  IF v_course_id IS NULL OR v_user_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- Считаем общее количество уроков и пройденных
  SELECT COUNT(*) INTO v_total FROM lessons WHERE course_id = v_course_id;
  IF v_total = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT COUNT(*) INTO v_done
  FROM lesson_progress lp
  JOIN lessons l ON l.id = lp.lesson_id
  WHERE l.course_id = v_course_id
    AND lp.user_id = v_user_id
    AND lp.completed = true;

  v_progress := LEAST(100, GREATEST(0, (v_done * 100) / v_total));

  -- Обновляем enrollment, если он существует и прогресс изменился в большую сторону
  -- (не уменьшаем прогресс автоматически, чтобы не откатывать ручные правки)
  UPDATE enrollments
  SET progress = v_progress
  WHERE user_id = v_user_id
    AND course_id = v_course_id
    AND progress < v_progress;

  RETURN COALESCE(NEW, OLD);
END;
$function$
